quests[52745] = { id = 52745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yuke Needs Help!" }
quests[52746] = { id = 52746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Cache", description = "First things first. Remember... this is a war.\n\nWe accomplish nothing by simply adding the Zandalari to our ranks. We eventually need to crush the Alliance.\n\nYou and I will be leading operations in Kul Tiras. But first, we need resources.", completion = "<Nathanos looks over the gathered resources.>\n\nThis should do it.", objectives = "Gather 100 War Resources. War Resources can be obtained from many sources, including quests and treasure chests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52748] = { id = 52748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes on the Skies", description = "You have made a great deal of progress with Kua'fon. He may not yet possess de power of flight, but he is healthy and growing.\n\nTake de success you have made and build upon it, {name}. Do not let Pa'ku's lesson dishearten you.\n\nContinue to do as you have been. Nurture Kua'fon, build his confidence in his wings. Show him de way forward and he will reward you with a bond stronger than any you have ever known.\n\nWhen his wings are large enough to shade you, we will try again.", completion = "<Kua'fon spreads his magnificent wings.>\n\nSkree!", objectives = "Tend to Kua'fon until he is fully grown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52749] = { id = 52749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Campaign", description = "{name}, a moment of your time.\n\nBefore you leave the city, speak with me out on the Banshee's Wail, on the docks. I have information to discuss with you about the war against the Alliance.", completion = "You're here.", objectives = "Report to Nathanos Blightcaller aboard the Banshee's Wail in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52750] = { id = 52750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmers Who Fight", description = "I was hoping for a squad of Proudmoore Academy's finest, but I guess you'll have to do.\n\nWhat we lack in manpower we make up for in courage! Even the farmers here won't give up their land without a fight.\n\nSend the bravest of them to me. They will fight better alongside our marines than by themselves out in the fields!", completion = "We'll get those volunteers paired up with the regulars and give 'em a fighting chance.", objectives = "Recruit 6 Vigil Hill Farmers into the militia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52751] = { id = 52751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Looking Dogs", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52752] = { id = 52752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vigilant Lookouts" }
quests[52754] = { id = 52754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marshdwellers", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52755] = { id = 52755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing the Heat" }
