quests[52851] = { id = 52851, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Mugamba Overlook", description = "Your followers have sent a report regarding the assault on Mugamba Overlook.\n\nIt details that victory was hard-fought, but the enemies guarding the outpost have been slain.\n\nDeliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", progress = "Do you have news regarding the mission to Zuldazar?", completion = "It seems the mission to create an additional foothold in Zuldazar was a success. Well done, {name}.\n\nI will send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52852] = { id = 52852, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mugamba Overlook", description = "The raid you planned for Mugamba Overlook in Zuldazar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mugamba Overlook in Zuldazar and establish fortifications there.\n\nMugamba Overlook will be an essential outpost in our campaign against the Horde.\n\nFor the Alliance!", completion = "This will make a fine outpost. It is well-hidden and nearly impassable by foot. The Horde will never suspect that we've made camp here.", objectives = "Claim Mugamba Overlook for the Alliance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52855] = { id = 52855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemy is an Inexact Science", description = "Hey, look.\n\nIt worked, right? Mostly. I mean, it DID get bigger. Don't look at me like that! So there are some... weird side effects going on. When has that ever gotten in the way of science before?\n\nOkay, okay, okay!\n\nI have an idea. Go and get me everything on this list. And be quick about it! I think these Zandalari might do something to me if you-- if WE-- don't fix this.\n\n<Alexxi hastily pens a list of ingredients and hands it to you.>\n\nDo me a solid, eh?", progress = "Those claws look really sharp, {name}. Do you have what I need?", completion = "Whew! Maybe this will calm them down.", objectives = "Gather 1 Crown of Torcali and 8 Glowfly Incandescence for Trader Alexxi in Warbeast Kraal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52856] = { id = 52856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snakes on a Terrace", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52857] = { id = 52857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Held For Observation", description = "<Trader Alexxi hurriedly combines the ingredients.>\n\nThat should do it. Go on and get this down your direhorn's gullet.\n\nDon't worry, nothing could possibly go wrong with a concoction made under any kind of duress. Also, do I seem like the kind of goblin who would give you something dangerous?\n\nOn purpose?\n\n... Don't answer that. Hurry, before they stab me.", progress = "<The direhorn hiccoughs in distress.>", completion = "<Beastlord L'kala peers mistrustfully at Alexxi, then back at you.>\n\nNone of this was necessary. Go. I need time to determine what is to be done about your direhorn.", objectives = "Administer the remedy to your direhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52858] = { id = 52858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Empowerment" }
quests[52861] = { id = 52861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lilian Voss", objectives = "I have fought alongside you in this campaign for some time now, {name}.\n\nWe have witnessed firsthand the lengths that the Horde will go to to win. It may not always be pretty, but in the end we have achieved the upper hand.\n\nI am curious to watch what Sylvanas does next. I am also curious to watch you.\n\nYou are an honorable man, {name}. Allow me to continue this fight by your side.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
