quests[52930] = { id = 52930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arathi Donations: Gold", description = "Our friends here are accepting all kinds of donations on behalf of the war effort, but if ya ask me, no battle was ever won without proper funding. That's right, bub. I'm talking about money! And lots of it.\n\nIf you got it, we need it!", progress = "A {class} like you's surely gotta have a little extra cash in your stash.\n\nWaddaya say? Lemme help lighten your load a bit?", completion = "Ain't nothin' more valuable than sweet, sweet gold.", objectives = "Donate 1000000 Gold to Paymaster Grintooth in the Port of Zandalar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
