quests[52942] = { id = 52942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoring Old Bonds", description = "We must speak to Grommash Hellscream and remind him of his debt to us. Everything rests on this mission, {name}.\n\nI hope your skills in diplomacy are greater than mine.\n\nBe on your guard; we do not know what to expect on the other side.", completion = "We're not dead yet. I suppose that is a good sign.", objectives = "Speak with Oculeth to travel to Draenor and meet with the Mag'har.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
